'use client';

import type { HTMLAttributes, PointerEvent } from 'react';
import './spotlight-card.css';

/** A card with a soft highlight that follows the pointer. */
export function SpotlightCard({
  className = '',
  children,
  ...rest
}: HTMLAttributes<HTMLDivElement>) {
  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    event.currentTarget.style.setProperty(
      '--mg-x',
      `${event.clientX - rect.left}px`
    );
    event.currentTarget.style.setProperty(
      '--mg-y',
      `${event.clientY - rect.top}px`
    );
  };
  return (
    <div
      className={`mg-spotlight ${className}`}
      onPointerMove={onPointerMove}
      {...rest}
    >
      {children}
    </div>
  );
}

.mg-spotlight {
  position: relative;
  overflow: hidden;
  padding: 24px;
  border: 1px solid #303030;
  border-radius: 16px;
  background: var(--mg-raised, #262626);
  color: #ffffff;
}

.mg-spotlight::before {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    200px circle at var(--mg-x, 50%) var(--mg-y, 0%),
    rgba(100, 138, 255, 0.32),
    rgba(0, 71, 255, 0.18) 45%,
    transparent 70%
  );
  content: '';
  opacity: 0;
  pointer-events: none;
  transition: opacity 300ms ease;
}

.mg-spotlight:hover::before,
.mg-spotlight:focus-within::before {
  opacity: 1;
}

.mg-spotlight > * {
  position: relative;
}

.mg-spotlight a {
  color: #8aa8ff;
}

@media (prefers-reduced-motion: reduce) {
  .mg-spotlight::before {
    transition: none;
  }
}
